import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")

    if platform.system() == "Windows":
        cmd = "wmic cpu get loadpercentage /value"
    else:
        cmd = "top -bn1 | grep 'Cpu(s)'"

    records = []
    end_time = time.time() + duration

    while time.time() < end_time:
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime())
        try:
            output = subprocess.check_output(cmd, shell=True).decode("utf-8")
            if platform.system() == "Windows":
                cpu_usage = int(output.split('=')[1].strip())
            else:
                cpu_usage = float(output.split(',')[0].split()[0].strip('%'))
        except Exception:
            cpu_usage = 0
        records.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w") as logfile:
            json.dump(records, logfile, indent=4)
    except IOError:
        return None

    return LOGFILE_PATH

