LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")

    platform_system = platform.system()
    cpu_usage_command = "wmic cpu get loadpercentage" if platform_system == "Windows" else "top -bn1 | grep 'Cpu(s)'"

    records = []
    end_time = time.time() + duration

    while time.time() < end_time:
        try:
            result = subprocess.run(cpu_usage_command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
            if platform_system == "Windows":
                cpu_usage = int(result.stdout.strip().split()[1])
            else:
                cpu_usage = float(result.stdout.split(',')[0].split()[1].strip('%'))
            records.append({"timestamp": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime()), "cpu_usage": cpu_usage})
        except Exception as e:
            print(f"Error capturing CPU usage: {e}", file=sys.stderr)
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w") as logfile:
            json.dump(records, logfile, indent=4)
    except IOError as e:
        print(f"IOError: {e}", file=sys.stderr)
        return None

    return LOGFILE_PATH

