import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.isdir(src_folder) or not os.path.isdir(dst_folder):
        raise OSError("Invalid source or destination folder")

    failed_files = []
    src_files = glob(os.path.join(src_folder, '*'))

    for file_path in src_files:
        try:
            base_name = os.path.basename(file_path)
            compressed_path = os.path.join(dst_folder, base_name + '.gz')
            subprocess.run(['gzip', '-c', file_path], stdout=open(compressed_path, 'wb'), check=True)
            os.remove(file_path)
        except Exception:
            failed_files.append(base_name)

    success = len(failed_files) == 0
    message = "All files compressed and moved successfully." if success else "Some files failed to compress or move."
    return {'success': success, 'message': message, 'failed_files': failed_files}

